<script setup>
import { computed } from 'vue';
import AppIcon from '../AppIcon.vue';
import { useObservedIntentSelection } from '../../composables/useObservedIntentSelection.js';
const props = defineProps({ grid: { type: Object, required: true }, expired: Boolean, selectionDisabled:Boolean, contextKey:{type:String,default:''} });
const emit=defineEmits(['apply']);
const {selectedRows,courtOrder,selection,selectionError,canSelect,chosen,toggle,clear,move,remove,apply}=useObservedIntentSelection(props,emit);
const states = {observed_clear_unmarked:'客户端可选',observed_reserved:'已预订',observed_activity_occupied:'活动占用',observed_unbookable:'不可预订',observed_unknown:'状态未知'};
const activityLabels=['其他活动','体育课','项目培训','体训队','艺术团','工会活动','其他活动'];
function label(cell){return cell.state==='observed_activity_occupied' ? activityLabels[cell.activity_type]||'活动占用' : states[cell.state];}
function cellClass(cell,isChosen=false){return isChosen?'official-selected':cell.state==='observed_activity_occupied'?`official-course-${cell.activity_type}`:`cell-${cell.state}`;}
const legend=[{name:'客户端可选',class:'cell-observed_clear_unmarked'},{name:'已选择',class:'official-selected'},{name:'已预订',class:'cell-observed_reserved'},...['体育课','项目培训','体训队','艺术团','工会活动','其他活动'].map((name,i)=>({name,class:`official-course-${i===5?0:i+1}`})),{name:'不可预订',class:'cell-observed_unbookable'},{name:'未知',class:'cell-observed_unknown'}];
const observedTime = computed(() => new Intl.DateTimeFormat('zh-CN', {
  dateStyle: 'short', timeStyle: 'medium', timeZone: props.grid.timezone_name,
}).format(props.grid.source.captured_at_utc_ms));
</script>

<template>
  <section class="observation-grid" data-testid="live-availability-grid" aria-labelledby="live-grid-title">
    <header class="observation-heading"><div><h3 id="live-grid-title">{{ grid.query_scope.display_name }} · {{ grid.target_date }}</h3></div><span class="observation-badge">{{ expired ? '观察已过期' : '当前读取观察' }}</span></header>
    <p class="observation-notice"><AppIcon name="info" />按客户端状态选意向 · 不下单</p>
    <p class="muted observation-time">读取时间 {{ observedTime }}</p>
    <p v-if="expired" class="form-error" role="status" data-testid="live-grid-expired">观察已过期，请重新读取。</p>
    <div class="observation-legend" aria-label="官方显示状态"><span v-for="item in legend" :key="item.name"><i :class="item.class" aria-hidden="true" />{{ item.name }}</span></div>
    <div class="observation-scroll" role="region" aria-label="官方场地时间网格，选择预约意向" tabindex="0">
      <table class="observation-table">
        <caption class="sr-only">官方场地时间网格，选择首选与备选意向</caption>
        <thead><tr><th scope="col">时间标签</th><th v-for="(court,index) in grid.courts" :key="index" scope="col">{{ court.display_name }}</th></tr></thead>
        <tbody><tr v-for="(row,rowIndex) in grid.rows" :key="rowIndex"><th scope="row">{{ row.time_label }}</th><template v-if="row.time_status_code === '0'"><td v-for="(cell,courtIndex) in row.cells" :key="courtIndex"><button type="button" class="observation-cell" :class="cellClass(cell,chosen(rowIndex,courtIndex))" :data-testid="`live-cell-${rowIndex}-${courtIndex}`" :title="`${label(cell)}${row.intent_end_time?' · '+row.time_label+'～'+row.intent_end_time:''}`" :aria-label="`${grid.courts[courtIndex].display_name} ${row.time_label}：${chosen(rowIndex,courtIndex)?'已选择':label(cell)}`" :aria-pressed="chosen(rowIndex,courtIndex)" :disabled="!canSelect(rowIndex,courtIndex)" @click="toggle(rowIndex,courtIndex)"><AppIcon v-if="chosen(rowIndex,courtIndex)" name="check" /><AppIcon v-else-if="cell.state==='observed_reserved'" name="lock" /><AppIcon v-else-if="cell.state==='observed_unknown'" name="info" /><span v-else class="sr-only">{{ label(cell) }}</span></button></td></template><td v-else :colspan="grid.courts.length" class="muted">{{ row.time_status_code === '1' ? '此时段未展示' : '状态未知' }}</td></tr></tbody>

      </table>
    </div>
    <div v-if="selectedRows.size" class="observed-selection">
      <strong>{{ selection.valid?`${selection.start}～${selection.end} · ${selection.duration}分钟`:selection.message }}</strong>
      <ol><li v-for="(court,index) in courtOrder" :key="court"><span>{{ index===0?'首选':'备选 '+index }} · {{ grid.courts[court].display_name }}</span><div><button type="button" :disabled="index===0" :aria-label="`将场地 ${index+1} 提前`" @click="move(index,-1)"><AppIcon name="up" /></button><button type="button" :disabled="index===courtOrder.length-1" :aria-label="`将场地 ${index+1} 后移`" @click="move(index,1)"><AppIcon name="down" /></button><button type="button" :aria-label="`移除场地 ${index+1}`" @click="remove(index)"><AppIcon name="close" /></button></div></li></ol>
      <p class="muted">按顺序只尝试一个场地；点击相同时段的其他场地添加备选。</p>
      <div class="observed-selection-actions"><button class="primary-button" data-testid="apply-live-selection" type="button" :disabled="!selection.valid||expired" @click="apply">确认选择</button><button class="secondary-button" type="button" @click="clear">清空</button></div>
    </div>
    <p v-if="selectionError" role="status" class="form-error">{{ selectionError }}</p>
    <details class="observation-source-details"><summary><AppIcon name="info" />数据来源</summary><p class="muted">{{ grid.notice }}</p><p class="muted">仅保留 60 秒显示新鲜度；这不是平台保证的库存有效期。价格单位尚未核验，金额已隐藏。白色仅表示客户端当前显示可选，不保证下单成功。相邻时间标签只用于表达意向边界，不证明上游原子时长。确认仅填入未绑定语义意向；不会参与 Matcher 或产生订单。</p></details>
  </section>
</template>

<style scoped>
