d:var(--page);color:var(--muted)}@media(max-width:600px){.observation-table th,.observation-table td{min-width:82px;padding:5px}.observation-table th:first-child{min-width:70px}.observation-cell{min-height:44px}}
.observation-heading h3{font-size:15px}.observation-heading .observation-badge{font-size:12px;padding:4px 7px}.observation-notice{display:flex;align-items:center;gap:5px;padding:0;background:none;font-size:12px}.observation-notice .app-icon{width:15px;height:15px}.observation-time{font-size:12px;margin:0}.observation-legend{gap:6px}.observation-legend span{display:flex;align-items:center;gap:4px;padding:3px 6px;font-size:12px}.observation-legend .app-icon{width:13px;height:13px}.observation-cell .app-icon{width:17px;height:17px}.observation-source-details{font-size:12px;color:var(--muted)}.observation-source-details summary{display:flex;align-items:center;gap:4px;cursor:pointer;min-height:30px;width:fit-content}.observation-source-details .app-icon{width:16px;height:16px}.observation-source-details p{line-height:1.6}

/* Exact colors from req/1.js bookingByTime CSS; source-specific, not global theme. */
.observation-grid{--official-clear:#fff;--official-selected:#f29f11;--official-reserved:#0762c7;--official-disabled:#c8c8c8;--official-other:#c6e0b4;--official-pe:#ffe8a3;--official-training:#b4c6e5;--official-team:#f8e1c5;--official-art:#9bc2e4;--official-union:#f4b084}
.cell-observed_clear_unmarked{background:var(--official-clear);color:var(--ink)}.official-selected{background:var(--official-selected);color:var(--ink)}.cell-observed_reserved{background:var(--official-reserved);color:#fff}.cell-observed_unbookable{background:var(--official-disabled);color:var(--ink)}.cell-observed_unknown{background:repeating-linear-gradient(135deg,var(--page),var(--page) 4px,var(--line) 4px,var(--line) 8px);color:var(--ink)}.official-course-0,.official-course-6{background:var(--official-other);color:var(--ink)}.official-course-1{background:var(--official-pe);color:var(--ink)}.official-course-2{background:var(--official-training);color:var(--ink)}.official-course-3{background:var(--official-team);color:var(--ink)}.official-course-4{background:var(--official-art);color:var(--ink)}.official-course-5{background:var(--official-union);color:var(--ink)}
.observation-cell{width:100%;min-height:44px;border:1px solid var(--line);cursor:pointer}.observation-cell:disabled{opacity:1;cursor:not-allowed}.observation-cell:focus-visible{outline:3px solid var(--brand);outline-offset:1px}.observation-legend span{background:none;color:var(--muted);gap:4px;padding:2px;font-size:12px}.observation-legend i{width:12px;height:12px;flex-shrink:0;border:1px solid var(--line);border-radius:2px}.observed-selection{border:1px solid var(--line);border-radius:8px;padding:12px;font-size:14px}.observed-selection ol{padding:0;margin:8px 0;list-style:none}.observed-selection li{display:flex;justify-content:space-between;align-items:center;gap:8px}.observed-selection li>div{display:flex;gap:4px}.observed-selection li button{display:grid;place-items:center;width:44px;height:44px;border:1px solid var(--line);border-radius:6px;background:var(--surface);color:var(--ink);cursor:pointer}.observed-selection p{font-size:12px;margin:4px 0 12px}.observed-selection-actions{display:flex;gap:8px}
